/* cppi::188129eabdbe7bd78474a11426ff747c36821e37d0cad452a90876730a6abafc */
SELECT *
FROM holdings.scd_holdings_main
TABLESAMPLE BERNOULLI(.001)
ORDER BY business_date limit 500 -- {"user": "siminwang@cppib.com", "source": "pyxll"}

/* cppi::1e4422d394a2d94f30e770470eafe1dfb83afcb41e447a888308b9b01f548fb2 */
/* QuickSight ef65ddc3-aa7f-4a80-974f-422f81311150 */
SELECT "video_url", "title", CAST(PARSE_DATETIME("published", 'yyyy-MM-dd''T''HH:mm:ss''Z''') AS TIMESTAMP) AS "published", "description", "star_rating_count", "star_rating_average", "star_rating_min", "star_rating_max", "views", "year", "month", "day", REPLACE("video_url", 'https://www.youtube.com/watch?v=', 'embed/') AS "youtube_embedded_url"
FROM "AwsDataCatalog"."optimization_data"."aws_feeds_youtube"

/* cppi::9334b633b01fea3944f04a73f709b583afb3b321df58ecc6af5432d05cc48762 */
